const mongoose = require('mongoose');
const mongoURI = "mongodb://localhost:27017/social-parivartan";

const connectToMongo = async () => {
    try {
        await mongoose.connect(mongoURI);
        console.log("Conected To Mongo Successfully");
    } catch (error) {
        console.log(error);
    }
};

module.exports = connectToMongo;

const connectToMongo = require('./db');
const express = require('express')
const app = express()
const port = 5000
var cors = require('cors')

connectToMongo();


app.use(cors())
app.use(express.json())
app.use('/uploads', express.static('uploads'))


app.get('/', (req, res) => {
  res.send('Hello World!')
})
app.use('/api/auth',require('./routes/auth'));


app.listen(port, () => {
  console.log(`Social Parivartan is listening on port ${port}`)
})

var jwt = require('jsonwebtoken');
const JWT_SECRET = 'HRWells';


const fetchuser = (req, res, next) => {
   // Get the user from the jwt token and add it to the request object
   const token = req.header('auth-token');
   if (!token) {
     return res.status(401).json({ error: 'No auth token found, please login.' });
   }

   try {
     const data = jwt.verify(token, JWT_SECRET);
     req.user = data.user;
     next();
   } catch (error) {
     console.error(error);
     res.status(401).json({ error: 'Invalid auth token, please login again.' });
   }
 };


module.exports = fetchuser;

const mongoose = require('mongoose');
const { Schema } = mongoose;

const UserSchema = new Schema({
    firstName: {
        type: String,
        required: true
    }, lastName: {
        type: String,
        required: true
    },
    email: {
        type: String,
        required: true,
        unique: true
    },
    password: {
        type: String,
        required: true
    },
    // username: {
    //     type: String,
    //     required: true,
    //     unique: true
    // },
    gender: {
        type: String,
        required: false
    },
    bio: {
        type: String,
        required: false
    },
    location: {
        type: String,
        required: false
    },
    idOfAvatar: {
        type: String
    },
    followers: [{
        type: Schema.Types.ObjectId,
        ref: 'User'
    }],
    following: [{
        type: Schema.Types.ObjectId,
        ref: 'User'
    }],
    date: {
        type: Date,
        default: Date.now
    }
});

const User = mongoose.model('user', UserSchema);
module.exports = User;

