"use server";

import { signIn, signOut } from "@/auth";
import { prisma } from "@/prisma";
import { revalidatePath } from "next/cache";
import bcrypt from "bcryptjs";

export async function login(provider: string) {
  await signIn(provider, { redirectTo: "/" });
  revalidatePath("/");
}

export async function logout() {
  await signOut({ redirectTo: "/" });
  revalidatePath("/");
}

export async function credentialsSignIn(formData: FormData) {
  const email = formData.get("email") as string;
  const password = formData.get("password") as string;

  if (!email || !password) {
    return { error: "Email and password are required" };
  }

  try {
    const user = await prisma.user.findUnique({ where: { email } });

    if (user && !user?.password) {
      return {
        error:
          "Your account was created using a Google login. please try login using Google.",
      };
    }

    if (user && user.verified === false) {
      return {
        error: "Please verify your email before signing in",
        needsVerification: true,
        email,
      };
    }

    const result = await signIn("credentials", {
      email,
      password,
      redirect: false,
    });

    if (result?.error) {
      return { error: "Invalid email or password" };
    }

    return { success: true };
  } catch (error: unknown) {
    console.error("Sign in error:", error);

    if (
      typeof error === "object" &&
      error !== null &&
      "type" in error &&
      error.type === "CredentialsSignin"
    ) {
      return { error: "Invalid email or password" };
    }

    return { error: "Something went wrong. Please try again." };
  }
}

export async function credentialsSignUp(formData: FormData) {
  const name = formData.get("name") as string;
  const email = formData.get("email") as string;
  const password = formData.get("password") as string;

  if (!name || !email || !password) {
    return { error: "All fields are required" };
  }

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return { error: "Please enter a valid email address" };
  }

  if (password.length < 8) {
    return { error: "Password must be at least 8 characters long" };
  }

  if (!/(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/.test(password)) {
    return {
      error:
        "Password must contain at least one uppercase letter, one lowercase letter, and one number",
    };
  }

  try {
    const existingUser = await prisma.user.findUnique({
      where: { email },
    });

    if (existingUser) {
      return { error: "User with this email already exists" };
    }

    const hashedPassword = await bcrypt.hash(password, 12);

    await prisma.user.create({
      data: {
        name,
        email,
        password: hashedPassword,
        verified: false,
      },
    });

    const { createVerificationToken } = await import("@/lib/verification");
    const { sendVerificationEmail } = await import("@/lib/email");

    const token = await createVerificationToken(email);
    const emailResult = await sendVerificationEmail(email, token);

    if (!emailResult.success) {
      return {
        error:
          "Account created but failed to send verification email. Please contact support.",
      };
    }

    return {
      success: true,
      message:
        "Account created successfully! Please check your email to verify your account.",
    };
  } catch (error) {
    console.error("Sign up error:", error);
    return { error: "Failed to create account. Please try again." };
  }
}

export async function resendVerificationEmail(email: string) {
  try {
    const { resendVerificationEmail: checkResend } = await import(
      "@/lib/verification"
    );
    const eligibilityCheck = await checkResend(email);

    if (!eligibilityCheck.success) {
      return { error: eligibilityCheck.error };
    }

    const { createVerificationToken } = await import("@/lib/verification");
    const { sendVerificationEmail } = await import("@/lib/email");

    const token = await createVerificationToken(email);
    const emailResult = await sendVerificationEmail(email, token);

    if (!emailResult.success) {
      return { error: "Failed to send verification email" };
    }

    return { success: true, message: "Verification email sent successfully" };
  } catch (error) {
    console.error("Resend verification error:", error);
    return { error: "Failed to resend verification email" };
  }
}

"use client";

import { useState } from "react";
import { FaArrowLeft, FaMailBulk } from "react-icons/fa";
import Link from "next/link";
import toast from "react-hot-toast";

export default function ForgotPasswordPage() {
  const [loading, setLoading] = useState(false);
  const [emailSent, setEmailSent] = useState(false);
  const [email, setEmail] = useState("");

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setLoading(true);

    const formData = new FormData(e.currentTarget);
    const email = formData.get("email") as string;

    try {
      const response = await fetch("/api/auth/forgot-password", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ email }),
      });

      const result = await response.json();

      if (result.success) {
        setEmail(email);
        setEmailSent(true);
        toast.success("Password reset email sent!");
      } else {
        toast.error(result.error || "Failed to send reset email");
      }
    } catch (error) {
      console.log(error);
      toast.error("Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  if (emailSent) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-[#d8e9fe] to-[#62a4fa] flex items-center justify-center px-4">
        <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-8 text-center">
          <FaMailBulk className="w-16 h-16 text-[#13aa95] mx-auto mb-4" />
          <h1 className="text-2xl font-semibold text-gray-800 mb-2">
            Check Your Email
          </h1>
          <p className="text-gray-600 mb-6">
            We&apos;ve sent a password reset link to{" "}
            <span className="font-semibold">{email}</span>
          </p>
          <p className="text-sm text-gray-500 mb-6">
            If you don&apos;t see the email, check your spam folder or try
            again.
          </p>
          <div className="space-y-3">
            <button
              onClick={() => setEmailSent(false)}
              className="flex justify-center w-full bg-sec hover:bg-[#13aa95] text-white font-semibold py-2 px-4 rounded-xl transition-colors cursor-pointer"
            >
              Send Another Email
            </button>
            <Link
              href="/sign-in"
              className="block w-full border border-slate-300 hover:bg-slate-100 text-gray-700 font-semibold py-2 px-4 rounded-xl transition-colors"
            >
              Back to Sign In
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#d8e9fe] to-[#62a4fa] flex items-center justify-center px-4">
      <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-8">
        <div className="mb-6">
          <Link
            href="/sign-in"
            className="inline-flex items-center gap-2 text-gray-600 hover:text-gray-800 transition-colors"
          >
            <FaArrowLeft className="w-4 h-4" />
            Back to Sign In
          </Link>
        </div>

        <div className="text-center mb-8">
          <h1 className="text-2xl font-semibold text-gray-800 mb-2">
            Forgot Password?
          </h1>
          <p className="text-gray-600">
            Enter your email address and we&apos;ll send you a link to reset
            your password.
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <input
              type="email"
              name="email"
              required
              placeholder="Enter your email address"
              className="w-full border border-slate-300 rounded-xl px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-sec focus:border-transparent"
              disabled={loading}
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-sec hover:bg-[#13aa95] disabled:bg-gray-400 disabled:cursor-not-allowed text-white font-semibold py-2 px-4 rounded-xl transition-colors cursor-pointer"
          >
            {loading ? "Sending..." : "Send Reset Email"}
          </button>
        </form>

        <div className="mt-6 text-center">
          <p className="text-sm text-gray-500">
            Remember your password?
            <Link
              href="/sign-in"
              className="text-sec hover:text-[#13aa95] font-semibold"
            >
              Sign in
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
}

