import { PrismaAdapter } from "@auth/prisma-adapter";
import { prisma } from "@/prisma";
import NextAuth from "next-auth";
import Google from "next-auth/providers/google";
import Credentials from "next-auth/providers/credentials";
import bcrypt from "bcryptjs";

export const { handlers, signIn, signOut, auth } = NextAuth({
  adapter: PrismaAdapter(prisma),
  session: { strategy: "jwt" },
  providers: [
    Google({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    }),
    Credentials({
      name: "credentials",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      async authorize(credentials) {
        const creds = credentials as { email: string; password: string };

        if (!creds?.email || !creds?.password) {
          console.log("Missing email or password");
          return null;
        }

        try {
          const user = await prisma.user.findUnique({
            where: { email: creds.email },
          });

          if (!user || !user.password) {
            console.log("User not found or password missing");
            return null;
          }

          const isPasswordValid = await bcrypt.compare(
            creds.password,
            user.password
          );

          if (!isPasswordValid) {
            console.log("Invalid password");
            return null;
          }

          if (!user.verified) {
            console.log("User email not verified");
            return null;
          }

          console.log("User authenticated:", user.email);

          return {
            id: user.id,
            email: user.email,
            name: user.name,
            image: user.image,
          };
        } catch (error) {
          console.error("Authentication error:", error);
          return null;
        }
      },
    }),
  ],
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.id = user.id;
      }
      return token;
    },
    async session({ session, token }) {
      if (token) {
        session.user.id = token.id as string;
      }
      return session;
    },
  },
  pages: {
    signIn: "/sign-in",
  },
  events: {
    async signIn(message) {
      if (message.account && message.account.provider === "google") {
        const email = message.user?.email;

        if (email) {
          await prisma.user.update({
            where: { email },
            data: { verified: true },
          });
        } else {
          console.error("Google user email is missing.");
        }
      }
    },
  },
});

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import toast from "react-hot-toast";
import { credentialsSignIn } from "@/actions/auth";
import Link from "next/link";
import useAuthStore from "@/store/authStore";
import { FaEye, FaEyeSlash } from "react-icons/fa";

export default function CredentialsSignInForm() {
  const [loading, setLoading] = useState(false);
  const [showResendVerification, setShowResendVerification] = useState(false);
  const [unverifiedEmail, setUnverifiedEmail] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const { setIsLoggedIn } = useAuthStore();

  const router = useRouter();

  async function handleSubmit(formData: FormData) {
    setLoading(true);

    const result = await credentialsSignIn(formData);

    if (result?.error) {
      if (result.needsVerification && result.email) {
        setUnverifiedEmail(result.email);
        setShowResendVerification(true);
        toast.error(result.error);
        setLoading(false);
      } else {
        toast.error(result.error);
        setLoading(false);
      }
    } else {
      toast.success("Signed in successfully!");
      setLoading(false);
      setIsLoggedIn(true);
      setTimeout(() => {
        router.push("/");
      }, 800);
    }
  }

  async function handleResendVerification() {
    try {
      const response = await fetch("/api/auth/resend-verification", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ email: unverifiedEmail }),
      });

      const result = await response.json();

      if (result.success) {
        toast.success("Verification email sent! Please check your inbox.");
        setShowResendVerification(false);
      } else {
        toast.error(result.error || "Failed to resend verification email");
      }
    } catch (error) {
      toast.error("Something went wrong. Please try again.");
      console.log(error);
    }
  }

  return (
    <div className="w-full space-y-4">
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const formData = new FormData(e.currentTarget);
          handleSubmit(formData);
        }}
        className="w-full flex flex-col gap-3"
      >
        <input
          type="email"
          name="email"
          required
          placeholder="Email"
          className="border border-slate-300 rounded-xl px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-sec focus:border-transparent"
          disabled={loading}
          autoComplete="off"
        />
        <div className="relative">
          <input
            type={showPassword ? "text" : "password"}
            name="password"
            required
            placeholder="Password"
            className="flex w-full justify-center items-center border border-slate-300 rounded-xl px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-sec focus:border-transparent"
            disabled={loading}
          />
          <span
            onClick={() => setShowPassword(!showPassword)}
            className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500 hover:text-gray-700"
          >
            {showPassword ? (
              <FaEyeSlash className="w-5 h-5" />
            ) : (
              <FaEye className="w-5 h-5" />
            )}
          </span>
        </div>
        <button
          type="submit"
          disabled={loading}
          className="bg-sec hover:bg-[#13aa95] cursor-pointer disabled:bg-gray-400 disabled:cursor-not-allowed w-full rounded-xl px-4 py-2 text-white font-semibold transition-colors"
        >
          {loading ? "Signing in..." : "Sign In"}
        </button>
        <div className="text-start text-[0.85rem] -mt-1 text-slate-600">
          <Link
            href="/forgot-password"
            className="text-sec hover:text-[#13aa95] font-normal"
          >
            Forgot password?
          </Link>
        </div>
      </form>

      {showResendVerification && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <p className="text-sm text-yellow-800 mb-3">
            Your email address is not verified. Please check your email for a
            verification link.
          </p>
          <button
            onClick={handleResendVerification}
            className="text-sm w-full cursor-pointer bg-yellow-600 hover:bg-yellow-700 text-white px-4 py-2 rounded-xl transition-colors"
          >
            Resend Verification Email
          </button>
        </div>
      )}

      <div className="text-center text-sm text-slate-600">
        Don&apos;t have an account?{" "}
        <Link
          href="/sign-up"
          className="text-sec hover:text-[#13aa95] font-semibold"
        >
          Sign up
        </Link>
      </div>
    </div>
  );
}

