+
+export default function CredentialsSignUpForm() {
+  const [loading, setLoading] = useState(false);
+
+  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
+    e.preventDefault();
+    setLoading(true);
+
+    toast.success("Account created successfully");
+
+    setLoading(false);
+  }
