                  />
                </div>

                {/* Active toggle */}
                <div className="flex items-center gap-2 mt-2">
                  <input
                    id="active"
                    type="checkbox"
                    name="active"
                    checked={form.active}
                    onChange={handleChange}
                    className="h-4 w-4 rounded border-slate-300 text-amber-600 focus:ring-amber-500"
                  />
                  <label
                    htmlFor="active"
                    className="text-sm font-medium text-slate-700"
