      try {
        // Fetch products
        const productSnapshot = await getDocs(collection(db, 'products'));
        const productList = productSnapshot.docs.map((doc) => ({
          id: doc.id,
          name: doc.data().name,
          price: doc.data().price || 0,
        }));
        setProducts(productList);

        // Fetch orders
        const orderSnapshot = await getDocs(collection(db, 'orders'));
        const ordersList = orderSnapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));

        // Attach product names + compute total + derive status + lastUpdate from events/updatedAt
        const ordersWithComputed = ordersList.map((order) => {
          // Products mapping
          const rawProducts = Array.isArray(order.products)
            ? order.products
            : [];

          const productsWithNames = rawProducts.map((p) => {
            const product = productList.find((prod) => prod.id === p.productId);
            return {
              ...p,
              name: product ? product.name : `Unknown (${p.productId})`,
              price: product ? product.price : 0,
            };
          });

          const total = productsWithNames.reduce(
            (sum, p) => sum + p.price * (p.quantity || 0),
            0
          );

          // Status + lastUpdate from events/updatedAt
          const events = Array.isArray(order.events) ? order.events : [];
          let latestEvent = null;

          if (events.length > 0) {
            latestEvent = events.reduce((latest, evt) => {
              const latestTs = latest?.timestamp ?? 0;
              const evtTs = evt?.timestamp ?? 0;
              return evtTs > latestTs ? evt : latest;
            }, null);
          }

          const rawStatus =
            latestEvent?.status ||
            order.status ||
            order.paymentStatus ||
            'processing';

          const normalized = normalizeStatus(rawStatus);

          let lastUpdateMs = 0;

          if (latestEvent?.timestamp) {
            // You stored timestamp as a number (ms) in events
            lastUpdateMs = latestEvent.timestamp;
          } else if (order.updatedAt?.toDate) {
            lastUpdateMs = order.updatedAt.toDate().getTime();
          } else if (order.updatedAt) {
            lastUpdateMs = new Date(order.updatedAt).getTime();
          }

          return {
            ...order,
            products: productsWithNames,
            total,
            status: normalized,
            rawStatus,
            // store numeric ms for easy sorting
            lastUpdate: lastUpdateMs || null,
          };
        });

        setOrders(ordersWithComputed);
      } catch (error) {
        console.error('Error fetching orders:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const filteredOrders = useMemo(() => {
  let filtered = [...orders];

  // PROCESSING = paid, label_created, processing
  if (filter === 'processing') {
    filtered = filtered.filter((o) => {
      const s = o.rawStatus?.toLowerCase() || '';
      return (
        s === 'paid' ||
        s === 'label_created' ||
        s === 'processing'
      );
    });
  }

  // IN TRANSIT = in_transit, out_for_delivery
  if (filter === 'transit') {
    filtered = filtered.filter((o) => {
      const s = o.rawStatus?.toLowerCase() || '';
      return (
        s === 'in_transit' ||
        s === 'out_for_delivery'
      );
    });
  }

  // DELIVERED
  if (filter === 'delivered') {
    filtered = filtered.filter((o) => {
      const s = o.rawStatus?.toLowerCase() || '';
      return s === 'delivered';
    });
  }

  // SEARCH FILTER
  if (searchTerm.trim() !== '') {
    const term = searchTerm.toLowerCase();
    filtered = filtered.filter((order) => {
      const productsText = Array.isArray(order.products)
        ? order.products.map((p) => p.name).join(' ')
        : '';

      const text =
        (order.trackingNumber || '') +
        ' ' +
        (order.status || '') +
        ' ' +
        productsText;

      return text.toLowerCase().includes(term);
    });
  }

  return filtered;
}, [orders, filter, searchTerm]);


  const summary = useMemo(() => {
    const totalOrders = orders.length;
    const totalRevenue = orders.reduce((sum, o) => sum + (o.total || 0), 0);
    const inTransit = orders.filter((o) => {
      const s = (o.status || '').toLowerCase();
      return s === 'in transit' || s === 'out for delivery';
    }).length;

    return { totalOrders, totalRevenue, inTransit };
  }, [orders]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 via-amber-50 to-white">
      <div className="mx-auto max-w-7xl px-4 py-10 space-y-6">
        {/* Header */}
        <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-gray-900">
              Orders
            </h1>
            <p className="mt-1 text-sm text-gray-500">
              View and manage all customer orders from Firebase.
            </p>
          </div>

          {/* Summary chips */}
          <div className="grid grid-cols-3 gap-3 text-xs sm:text-sm">
            <div className="rounded-xl bg-white/80 backdrop-blur border border-orange-100 px-3 py-2 shadow-sm flex items-center gap-2">
              <PackageSearch className="h-4 w-4 text-orange-500" />
              <div className="leading-tight">
                <div className="text-[11px] uppercase tracking-wide text-gray-500">
                  Total Orders
                </div>
                <div className="font-semibold text-gray-900 text-sm">
                  {summary.totalOrders}
                </div>
              </div>
            </div>
            <div className="rounded-xl bg-white/80 backdrop-blur border border-emerald-100 px-3 py-2 shadow-sm flex items-center gap-2">
              <Clock className="h-4 w-4 text-emerald-500" />
              <div className="leading-tight">
                <div className="text-[11px] uppercase tracking-wide text-gray-500">
                  Total Revenue
                </div>
                <div className="font-semibold text-gray-900 text-sm">
                  ${summary.totalRevenue.toFixed(2)}
                </div>
              </div>
            </div>
            <div className="rounded-xl bg-white/80 backdrop-blur border border-blue-100 px-3 py-2 shadow-sm flex items-center gap-2">
              <Truck className="h-4 w-4 text-blue-500" />
              <div className="leading-tight">
                <div className="text-[11px] uppercase tracking-wide text-gray-500">
                  In Transit
                </div>
                <div className="font-semibold text-gray-900 text-sm">
                  {summary.inTransit}
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Controls */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          {/* Search */}
          <div className="relative w-full sm:max-w-md">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
            <input
              type="text"
              className="w-full pl-9 pr-3 py-2 rounded-lg border border-orange-200 bg-white/80 text-sm focus:outline-none focus:ring-2 focus:ring-orange-400/70 focus:border-orange-400"
              placeholder="Search by tracking #, status, or product..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          {/* Filter pills */}
          <div className="flex items-center gap-2">
            <button
              className={`px-3 py-1.5 rounded-full text-xs sm:text-sm border transition ${
                filter === 'processing'
                  ? 'bg-orange-600 text-white border-orange-600 shadow-sm'
                  : 'border-orange-200 text-orange-700 bg-orange-50 hover:bg-orange-100'
              }`}
              onClick={() => setFilter('processing')}
            >
              Processing
            </button>

            <button
              className={`px-3 py-1.5 rounded-full text-xs sm:text-sm border transition ${
                filter === 'transit'
                  ? 'bg-orange-600 text-white border-orange-600 shadow-sm'
                  : 'border-orange-200 text-orange-700 bg-orange-50 hover:bg-orange-100'
              }`}
              onClick={() => setFilter('transit')}
            >
              In Transit
            </button>

            <button
              className={`px-3 py-1.5 rounded-full text-xs sm:text-sm border transition ${
                filter === 'delivered'
                  ? 'bg-orange-600 text-white border-orange-600 shadow-sm'
                  : 'border-orange-200 text-orange-700 bg-orange-50 hover:bg-orange-100'
              }`}
              onClick={() => setFilter('delivered')}
            >
              Delivered
            </button>

            <button
              className={`px-3 py-1.5 rounded-full text-xs sm:text-sm border transition ${
                filter === 'all'
                  ? 'bg-gray-900 text-white border-gray-900 shadow-sm'
                  : 'border-gray-300 text-gray-700 bg-white hover:bg-gray-50'
