        </div>
      </div>
    </div>
  );
}

"use client";
import React, { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { doc, getDoc, updateDoc, collection, getDocs, orderBy, query as fsQuery } from "firebase/firestore";
import { db } from "@/app/api/firebase/firebase";
import Link from "next/link";

export default function Page({ params }) {
	// Next.js may pass `params` as a Promise to client components.
	// Unwrap it using React.use() as recommended by Next.js migration messages.
	const resolvedParams = React.use(params) ?? {};
	const id = resolvedParams?.products;
	const router = useRouter();

	const [loading, setLoading] = useState(true);
	const [saving, setSaving] = useState(false);
	const [product, setProduct] = useState({
		name: "",
		price: 0,
		stock: 0,
		category: "",
		sku: "",
		image: "",
		description: "",
	});

	const [categories, setCategories] = useState([]);

	useEffect(() => {
		if (!id) return;
		let alive = true;

		(async () => {
			try {
				const ref = doc(db, "products", id);
				const snap = await getDoc(ref);
				if (!snap.exists()) {
					window.alert("Product not found");
					router.push("/admin/products");
					return;
				}
				const data = snap.data() || {};
				if (alive) setProduct({ id: snap.id, ...data });
			} catch (err) {
				console.error("Failed to load product", err);
				window.alert("Failed to load product. See console for details.");
			} finally {
				if (alive) setLoading(false);
			}
		})();

		// load categories for dropdown (optional)
		(async () => {
			try {
				const q = fsQuery(collection(db, "categories"), orderBy("name"));
				const snap = await getDocs(q);
				if (alive) {
					setCategories(
						snap.docs.map((d) => ({ label: d.data()?.name ?? d.id, value: (d.data()?.name ?? d.id).trim() }))
					);
				}
			} catch (e) {
				console.warn("Failed to load categories", e);
			}
		})();

		return () => {
			alive = false;
		};
	}, [id, router]);

	async function handleSave(e) {
		e.preventDefault();
		setSaving(true);
		try {
			const ref = doc(db, "products", id);
			const payload = {
				name: (product.name || "").trim(),
				price: Number(product.price) || 0,
				stock: Number(product.stock) || 0,
				category: product.category || "",
				sku: product.sku || "",
				image: product.image || "",
				description: product.description || "",
			};
			await updateDoc(ref, payload);
			window.alert("Product updated");
			router.push("/admin/products");
		} catch (err) {
			console.error("Failed to save product", err);
			window.alert("Failed to save product. See console for details.");
		} finally {
			setSaving(false);
		}
	}

	if (loading) {
		return (
			<div className="min-h-screen flex items-center justify-center">
				<div className="text-gray-600">Loading product…</div>
			</div>
		);
	}

	return (
		<div className="min-h-screen bg-gradient-to-br from-orange-50 via-amber-50 to-white p-6">
			<div className="max-w-3xl mx-auto bg-white rounded-2xl border border-orange-100 shadow p-6">
				<div className="flex items-center justify-between mb-4">
					<h2 className="text-2xl font-bold">Edit Product</h2>
					<Link href="/admin/products" className="text-sm text-gray-600 hover:underline">
						Back to products
					</Link>
				</div>

				<form onSubmit={handleSave} className="space-y-4">
					<div>
						<label className="block text-sm font-medium text-gray-700">Name</label>
						<input
							value={product.name}
							onChange={(e) => setProduct((p) => ({ ...p, name: e.target.value }))}
							className="mt-1 w-full rounded-xl border border-orange-200 px-3 py-2 text-sm"
						/>
					</div>

					<div className="grid grid-cols-2 gap-4">
						<div>
							<label className="block text-sm font-medium text-gray-700">Price</label>
							<input
								type="number"
								step="0.01"
								value={product.price}
								onChange={(e) => setProduct((p) => ({ ...p, price: e.target.value }))}
								className="mt-1 w-full rounded-xl border border-orange-200 px-3 py-2 text-sm"
							/>
						</div>
						<div>
							<label className="block text-sm font-medium text-gray-700">Stock</label>
							<input
								type="number"
								value={product.stock}
								onChange={(e) => setProduct((p) => ({ ...p, stock: e.target.value }))}
								className="mt-1 w-full rounded-xl border border-orange-200 px-3 py-2 text-sm"
							/>
						</div>
					</div>

					<div>
						<label className="block text-sm font-medium text-gray-700">Category</label>
						{categories.length > 0 ? (
							<select
								value={product.category}
								onChange={(e) => setProduct((p) => ({ ...p, category: e.target.value }))}
								className="mt-1 w-full rounded-xl border border-orange-200 px-3 py-2 text-sm"
							>
								<option value="">Select category</option>
								{categories.map((c) => (
									<option key={c.value} value={c.value}>
										{c.label}
									</option>
								))}
							</select>
						) : (
							<input
								value={product.category}
								onChange={(e) => setProduct((p) => ({ ...p, category: e.target.value }))}
								className="mt-1 w-full rounded-xl border border-orange-200 px-3 py-2 text-sm"
							/>
						)}
					</div>

					<div>
						<label className="block text-sm font-medium text-gray-700">SKU</label>
						<input
							value={product.sku}
							onChange={(e) => setProduct((p) => ({ ...p, sku: e.target.value }))}
							className="mt-1 w-full rounded-xl border border-orange-200 px-3 py-2 text-sm"
						/>
					</div>

					<div>
						<label className="block text-sm font-medium text-gray-700">Image URL</label>
						<input
							value={product.image}
							onChange={(e) => setProduct((p) => ({ ...p, image: e.target.value }))}
							className="mt-1 w-full rounded-xl border border-orange-200 px-3 py-2 text-sm"
						/>
					</div>

					<div>
						<label className="block text-sm font-medium text-gray-700">Description</label>
						<textarea
							value={product.description}
							onChange={(e) => setProduct((p) => ({ ...p, description: e.target.value }))}
							className="mt-1 w-full rounded-xl border border-orange-200 px-3 py-2 text-sm"
							rows={4}
						/>
					</div>

					<div className="flex items-center justify-end gap-3">
						<Link href="/admin/products" className="text-sm text-gray-600 hover:underline">
							Cancel
						</Link>
						<button
							type="submit"
							disabled={saving}
							className="bg-gradient-to-r from-orange-500 to-amber-500 text-white rounded-xl px-4 py-2 text-sm"
						>
							{saving ? "Saving…" : "Save changes"}
						</button>
					</div>
				</form>
			</div>
		</div>
	);
}

'use client';
import { storage } from '@/app/api/appwrite/appwrite';
import { ID } from 'appwrite';
import { useEffect, useState } from 'react';
import Link from 'next/link';
import { ArrowLeft, Upload, Package, Plus, X } from 'lucide-react';
import { db } from '@/app/api/firebase/firebase';
import {
  collection,
  getDocs,
  orderBy,
  query as fsQuery,
  serverTimestamp,
  addDoc,
  doc,
  setDoc,
  updateDoc,
} from 'firebase/firestore';
import { useRouter } from 'next/navigation';

export default function AddProductPage() {
  const router = useRouter();

  const [form, setForm] = useState({
    id: '', // optional custom Firestore doc id (string)
    sku: '',
    name: '',
    category: '',

    description: '',
    longDescription: '',
    price: '',
    rating: '',
    stock: '',
    inStock: true,
    image: '', // primary image url
    features: [''],
    specifications: [{ key: '', value: '' }],
  });
  const [imageFiles, setImageFiles] = useState([]);
  const [images, setImages] = useState([]); // local previews only
  const [submitting, setSubmitting] = useState(false);
  const [banner, setBanner] = useState({ type: '', msg: '' });
  const [catLoading, setCatLoading] = useState(true);
  const [catError, setCatError] = useState('');
  const [categories, setCategories] = useState([]); // [{label, value}]

  const onChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm((f) => ({ ...f, [name]: type === 'checkbox' ? checked : value }));
  };

  // ---- dynamic arrays/maps ----
  const addFeature = () =>
    setForm((f) => ({ ...f, features: [...f.features, ''] }));
  const setFeature = (i, v) =>
    setForm((f) => {
      const next = [...f.features];
      next[i] = v;
      return { ...f, features: next };
    });
  const removeFeature = (i) =>
    setForm((f) => ({
      ...f,
      features: f.features.filter((_, idx) => idx !== i),
    }));

  const addSpec = () =>
    setForm((f) => ({
      ...f,
      specifications: [...f.specifications, { key: '', value: '' }],
    }));
  const setSpec = (i, field, v) =>
    setForm((f) => {
      const next = [...f.specifications];
      next[i] = { ...next[i], [field]: v };
      return { ...f, specifications: next };
    });
  const removeSpec = (i) =>
    setForm((f) => ({
      ...f,
      specifications: f.specifications.filter((_, idx) => idx !== i),
    }));

  // ---- images (preview only) ----

  const handleImageUpload = (e) => {
    const files = Array.from(e.target.files || []);
    if (!files.length) return;

    // keep real files for upload
    setImageFiles((prev) => [...prev, ...files]);

    // keep local previews for UI only
    const previews = files.map((f) => URL.createObjectURL(f));
    setImages((prev) => [...prev, ...previews]);
  };

  const removePreview = (i) => {
    setImages((prev) => {
      URL.revokeObjectURL(prev[i]); // <-- revoke
      return prev.filter((_, idx) => idx !== i);
    });
    setImageFiles((prev) => prev.filter((_, idx) => idx !== i));
  };

  // cleanup on unmount
  useEffect(() => {
    return () => images.forEach((u) => URL.revokeObjectURL(u));
  }, [images]);

  // ---- validation + transform ----
  function validateAndBuildPayload() {
    const errors = [];

    const name = form.name.trim();
    const sku = form.sku.trim();
    const category = form.category.trim();

    const description = form.description.trim();
    const longDescription = form.longDescription.trim();
    const image = form.image.trim();

    const price = parseFloat(form.price);
    if (isNaN(price) || price < 0)
      errors.push('Price must be a non-negative number.');

    const rating = form.rating === '' ? null : parseFloat(form.rating);
    if (rating !== null && (isNaN(rating) || rating < 0 || rating > 5)) {
      errors.push('Rating must be between 0 and 5.');
    }

    const stock = parseInt(form.stock, 10);
    if (isNaN(stock) || stock < 0)
      errors.push('Stock must be a non-negative integer.');

    if (!name) errors.push('Product Name is required.');
    if (!sku) errors.push('SKU is required.');
    if (!category) errors.push('Category is required.');
    if (!description) errors.push('Description is required.');

    const features = (form.features || [])
      .map((s) => (s ?? '').trim())
      .filter(Boolean);

    const specifications = {};
    (form.specifications || []).forEach((row) => {
      const k = (row.key ?? '').trim();
      if (k) specifications[k] = row.value ?? '';
    });

    if (errors.length) return { ok: false, errors };

    // Build Firestore document
    const docBody = {
      sku,
      name,
      category,
      description,
      longDescription,
      price,
      rating: rating === null ? 0 : rating,
      stock,
      inStock: Boolean(form.inStock),
      image,
      images: [],
      features, // array<string>
      specifications, // map
      createdAt: serverTimestamp?.(),
    };

    // Optional: store 'id' inside doc body too
    if (form.id.trim()) docBody.id = String(form.id).trim();

    return { ok: true, data: docBody };
  }

  /* ---------- Appwrite file-type helpers ---------- */

  const ALLOWED_EXTENSIONS = ['jpg', 'jpeg', 'png', 'webp'];

  const getFileExtension = (file) => {
    const name = file?.name || '';
    const parts = name.split('.');
    if (parts.length < 2) return '';
    return parts.pop().toLowerCase();
  };

  const isAllowedFile = (file) => {
    const ext = getFileExtension(file);
    return ALLOWED_EXTENSIONS.includes(ext);
  };

  async function uploadAllProductImages(productId, files) {
    try {
      const urls = [];

      for (const file of files) {
        console.log('Uploading file:', file.name, file.type);

        if (!isAllowedFile(file)) {
          console.error('Blocked file with disallowed extension:', file.name);
          throw new Error(
            `File type not allowed: ${
              file.name
            }. Allowed: ${ALLOWED_EXTENSIONS.join(', ')}`
          );
        }

        const response = await storage.createFile(
          process.env.NEXT_PUBLIC_APPWRITE_BUCKET_ID,
          ID.unique(),
          file
        );

        const previewUrl = `${process.env.NEXT_PUBLIC_APPWRITE_ENDPOINT}/storage/buckets/${process.env.NEXT_PUBLIC_APPWRITE_BUCKET_ID}/files/${response.$id}/view?project=${process.env.NEXT_PUBLIC_APPWRITE_PROJECT_ID}&width=800&height=800&quality=90`;
        urls.push(previewUrl);
      }

      console.log('Uploaded URLS:', urls);
      return urls;
    } catch (err) {
      console.error('Appwrite upload error:', err);
      throw err;
    }
  }

