          </div>
        </div>

        {/* Status Tabs */}
        <div className="flex flex-wrap justify-center gap-3 mb-6">
          <button
            onClick={() => setActiveTab('current')}
            className={`px-6 py-2 rounded-full text-sm font-semibold transition ${
