          >
            Log In
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-8">
      {/* Tabs List */}
      <div className="backdrop-blur-lg border border-slate-200/30 bg-white/70 p-1 rounded-2xl shadow-lg inline-flex flex-wrap gap-2">
