                    ×
                  </button>
                </span>
              )}
              {stockFilter !== 'all' && (
                <span className="px-3 py-1 bg-amber-100 text-amber-800 rounded-full">
                  {stockFilter === 'instock' ? 'In Stock' : 'Out of Stock'}
                  <button
                    onClick={() => setStockFilter('all')}
                    className="ml-2 hover:text-amber-950"
                  >
