          </section>
        )}

        {/* All Products */}
        <section>
          <div className="mb-4 flex items-center justify-between text-sm text-slate-600">
            <p>
              Showing{' '}
              <span className="font-semibold text-slate-900">
                {filtered.length}
              </span>{' '}
