            </p>
          </div>

          <div
            className="
              grid gap-4 sm:gap-6
              [grid-template-columns:repeat(auto-fill,minmax(220px,1fr))]
              md:[grid-template-columns:repeat(auto-fill,minmax(240px,1fr))]
              xl:[grid-template-columns:repeat(auto-fill,minmax(260px,1fr))]
