          {role === 'admin' && (
            <Link
              href="/admin/dashboard"
              onClick={() => setOpen(false)}
              className="block w-full text-left px-4 py-3 rounded-xl text-slate-700 font-medium hover:text-amber-700 hover:bg-white/60 transition"
            >
