'use client';
import { useEffect, useState } from 'react';
import { collection, getDocs } from 'firebase/firestore';
import { db } from '@/app/api/firebase/firebase';

const DEFAULT_CATEGORIES = [
  { name: 'Power Tools', value: 35 },
  { name: 'Hand Tools', value: 25 },
  { name: 'Paint & Supplies', value: 20 },
  { name: 'Hardware', value: 20 },
];

// round helper to eliminate engine float drift
const round = (n, p = 3) => Number(n.toFixed(p));
const toRad = (deg) => (deg * Math.PI) / 180;

export default function CategoryDistribution({ data: initialData = null }) {
  const [data, setData] = useState(initialData || DEFAULT_CATEGORIES);
  const fills = ['#f97316', '#3b82f6', '#a855f7', '#10b981'];
  const lightingFill = '#fbbf24'; // yellow for Lighting category

  const radius = 40;
  const cx = 50;
  const cy = 50;

  useEffect(() => {
    // if parent passed data, don't fetch
    if (initialData) return;

    const fetchCategories = async () => {
      try {
        const snap = await getDocs(collection(db, 'products'));
        const counts = {};
        let total = 0;
        snap.forEach((doc) => {
          const product = doc.data();
          const cat = (product.category || 'Uncategorized').replace(
            /[-_]/g,
            ' '
          );
          counts[cat] = (counts[cat] || 0) + 1;
          total += 1;
        });

        if (total === 0) return;

        const computed = Object.entries(counts).map(([name, count]) => ({
          name,
          value: Math.round((count / total) * 100),
        }));

        // ensure we have percentages that sum to 100 (adjust drift)
        const sum = computed.reduce((s, c) => s + c.value, 0);
        if (sum !== 100 && computed.length > 0) {
          const diff = 100 - sum;
          computed[0].value += diff; // apply difference to first bucket
        }

        setData(computed);
      } catch (err) {
        console.error('Error fetching categories for distribution', err);
      }
    };

    fetchCategories();
  }, [initialData]);

  return (
    <div className="bg-white border border-orange-100 rounded-xl shadow-lg">
      <div className="p-5 border-b border-orange-100">
        <div className="text-gray-900 font-semibold">Category Distribution</div>
        <div className="text-gray-600 text-sm">Sales by category</div>
      </div>

      <div className="p-5">
        <div className="flex items-center justify-center mb-6">
          <div className="relative w-48 h-48">
            <svg viewBox="0 0 100 100" className="transform -rotate-90">
              {data.reduce((acc, category, index) => {
                const prevTotal = data
                  .slice(0, index)
                  .reduce((s, c) => s + c.value, 0);
                const startAngle = (prevTotal / 100) * 360;
                const endAngle = ((prevTotal + category.value) / 100) * 360;
                const largeArc = category.value > 50 ? 1 : 0;

                const [sx, sy] = [
                  round(cx + radius * Math.cos(toRad(startAngle))),
                  round(cy + radius * Math.sin(toRad(startAngle))),
                ];
                const [ex, ey] = [
                  round(cx + radius * Math.cos(toRad(endAngle))),
                  round(cy + radius * Math.sin(toRad(endAngle))),
                ];

                const isLighting = String(category.name || '').toLowerCase().trim() === 'lighting';
                const sliceFill = isLighting ? lightingFill : fills[index % fills.length];
                acc.push(
                  <path
                    key={index}
                    d={`M ${cx} ${cy} L ${sx} ${sy} A ${radius} ${radius} 0 ${largeArc} 1 ${ex} ${ey} Z`}
                    style={{ fill: sliceFill }}
                  />
                );
                return acc;
              }, [])}
            </svg>
          </div>
        </div>

        <div className="space-y-3">
          {data.map((category, index) => (
            <div key={index} className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div
                  className="w-4 h-4 rounded-full"
                  style={{ background: String(category.name || '').toLowerCase().trim() === 'lighting' ? lightingFill : fills[index % fills.length] }}
                />
                <span className="text-sm font-medium text-gray-900">
                  {category.name}
                </span>
              </div>
              <span className="text-sm font-bold text-gray-900">
                {category.value}%
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { TrendingUp } from 'lucide-react';
import { collection, query, where, getDocs, Timestamp } from 'firebase/firestore';
import { db } from '@/app/api/firebase/firebase';

const DEFAULT_GROWTH = { growth: 0, revenue: 0, customers: 0, products: 0 };

// Generic pct change helper
function pctChange(prev, curr) {
  if (prev === 0) {
    if (curr === 0) return 0;
    return 100; // previous 0, current > 0 → 100% growth
  }
  return ((curr - prev) / Math.abs(prev)) * 100;
}

// Try to read order amount robustly
function extractOrderAmount(data) {
  let amount =
    data?.total ??
    data?.orderTotal ??
    data?.amount ??
    data?.grandTotal ??
    0;

  if (typeof amount === 'string') {
    amount = parseFloat(amount) || 0;
  }

  // If stored in cents, normalize (very defensive)
  if (amount > 100000) {
    amount = amount / 100;
  }

  return Number.isFinite(amount) ? amount : 0;
}

export default function GrowthCard() {
  const [loading, setLoading] = useState(true);
  const [growthStats, setGrowthStats] = useState(DEFAULT_GROWTH);

  useEffect(() => {
    let mounted = true;

    async function fetchMoM() {
      setLoading(true);
      try {
        const now = new Date();
        const currentMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
        const nextMonthStart = new Date(now.getFullYear(), now.getMonth() + 1, 1);
        const prevMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);

        // Firestore timestamps for queries
        const currentMonthStartTS = Timestamp.fromDate(currentMonthStart);
        const nextMonthStartTS = Timestamp.fromDate(nextMonthStart);
        const prevMonthStartTS = Timestamp.fromDate(prevMonthStart);

        // -------- ORDERS: revenue + customers MoM (from Firestore) --------
        const ordersRef = collection(db, 'orders');
        const qCurrOrders = query(
          ordersRef,
          where('createdAt', '>=', currentMonthStartTS),
          where('createdAt', '<', nextMonthStartTS)
        );
        const qPrevOrders = query(
          ordersRef,
          where('createdAt', '>=', prevMonthStartTS),
          where('createdAt', '<', currentMonthStartTS)
        );

        const [currOrdersSnap, prevOrdersSnap] = await Promise.all([
          getDocs(qCurrOrders),
          getDocs(qPrevOrders),
        ]);

        // Revenue from orders
        let currRevenue = 0;
        currOrdersSnap.forEach((d) => {
          currRevenue += extractOrderAmount(d.data());
        });

        let prevRevenue = 0;
        prevOrdersSnap.forEach((d) => {
          prevRevenue += extractOrderAmount(d.data());
        });

        // Customers (unique)
        const currCustomers = new Set();
        currOrdersSnap.forEach((d) => {
          const data = d.data();
          const cust =
            data?.customer?.email ??
            data?.customer?.id ??
            data?.customerName ??
            data?.customer?.name;
          if (cust) currCustomers.add(cust);
        });

        const prevCustomers = new Set();
        prevOrdersSnap.forEach((d) => {
          const data = d.data();
          const cust =
            data?.customer?.email ??
            data?.customer?.id ??
            data?.customerName ??
            data?.customer?.name;
          if (cust) prevCustomers.add(cust);
        });

        // -------- PRODUCTS: catalog size MoM --------
        const productsRef = collection(db, 'products');
        const qPrevTotal = query(
          productsRef,
          where('createdAt', '<', currentMonthStartTS)
        );
        const qCurrTotal = query(
          productsRef,
          where('createdAt', '<', nextMonthStartTS)
        );

        const [prevTotalSnap, currTotalSnap] = await Promise.all([
          getDocs(qPrevTotal),
          getDocs(qCurrTotal),
        ]);

        const prevTotal = prevTotalSnap.size;
        const currTotal = currTotalSnap.size;

        // -------- Percent changes --------
        const revenuePct = Math.round(pctChange(prevRevenue, currRevenue) * 10) / 10;
        const customersPct =
          Math.round(pctChange(prevCustomers.size, currCustomers.size) * 10) / 10;
        const productsPct =
          Math.round(pctChange(prevTotal, currTotal) * 10) / 10;

        // Overall growth: average of available metrics
        const metrics = [revenuePct, customersPct, productsPct].filter(
          (n) => typeof n === 'number' && !Number.isNaN(n)
        );
        const overall = metrics.length
          ? Math.round(
              (metrics.reduce((a, b) => a + b, 0) / metrics.length) * 10
            ) / 10
          : 0;

        if (mounted) {
          setGrowthStats({
            growth: overall,
            revenue: revenuePct,
            customers: customersPct,
            products: productsPct,
          });
        }
      } catch (err) {
        console.error('Failed to compute growth from Firestore', err);
      } finally {
        if (mounted) setLoading(false);
      }
    }

    fetchMoM();
    return () => {
      mounted = false;
    };
  }, []);

  const { growth, revenue, customers, products } = growthStats;

  return (
    <div className="rounded-xl shadow-xl text-white bg-gradient-to-br from-orange-500 to-amber-500">
      <div className="p-5 border-b border-white/20 flex items-center justify-between">
        <div>
          <div className="text-2xl font-semibold">Growth Rate</div>
          <div className="text-orange-100 text-sm">
            Month-over-month performance
          </div>
        </div>
        <div className="w-12 h-12 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center">
          <TrendingUp className="w-6 h-6 text-white" />
        </div>
      </div>
      <div className="p-5">
        <div className="text-5xl font-bold mb-4">
          {loading ? '…' : `${growth >= 0 ? '+' : ''}${growth}%`}
        </div>
        <div className="space-y-2">
          <div className="flex items-center justify-between text-sm">
            <span className="text-orange-100">Revenue growth</span>
            <span className="font-semibold">
              {loading ? '…' : `${revenue >= 0 ? '+' : ''}${revenue}%`}
            </span>
          </div>
          <div className="flex items-center justify-between text-sm">
            <span className="text-orange-100">Customer growth</span>
            <span className="font-semibold">
              {loading ? '…' : `${customers >= 0 ? '+' : ''}${customers}%`}
            </span>
          </div>
          <div className="flex items-center justify-between text-sm">
            <span className="text-orange-100">Product expansion</span>
            <span className="font-semibold">
              {loading ? '…' : `${products >= 0 ? '+' : ''}${products}%`}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';
import { db } from '@/app/api/firebase/firebase';
import { addDoc, collection, Timestamp } from 'firebase/firestore';
import React, { useState } from 'react';

export default function NewCategoryModal({ onClose, onCreated }) {
  const [categoryName, setCategoryName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const slug = (s) => s.toLowerCase().trim().replace(/\s+/g, '-');

  const handleSubmit = async (e) => {
    e.preventDefault(); // 🔥 stop full page reload
    if (!categoryName.trim() || isSubmitting) return;

    setIsSubmitting(true);
    try {
      const name = categoryName.trim();
      const filterValue = slug(name);

      // 1) write to Firestore
      const docRef = await addDoc(collection(db, 'categories'), {
        name,
        filter: filterValue, // for catalog filters
        createdAt: Timestamp.now(),
      });

      // 2) build the object for parent state
      const newCategory = {
        id: docRef.id,
        name,
        filter: filterValue,
        createdAt: Timestamp.now(),
      };

      // 3) notify parent so it can push into categories[]
      onCreated?.(newCategory);

      // 4) close modal
      onClose?.();
      setCategoryName('');
    } catch (error) {
      console.error('Error adding category:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 flex items-center justify-center bg-black/10 z-50">
      <div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-md">
        <h2 className="text-xl font-semibold mb-4 text-center">New Category</h2>

        {/* FORM SUBMISSION */}
        <form onSubmit={handleSubmit}>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Category Name
          </label>
          <input
            type="text"
            placeholder="Name of new category"
            value={categoryName}
            onChange={(e) => setCategoryName(e.target.value)}
            className="w-full border rounded-lg p-2 mb-4 focus:outline-none focus:ring-2 focus:ring-orange-400"
            required
          />

          {/* CANCEL OR SUBMIT */}
          <div className="flex justify-end gap-2">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 rounded-lg bg-gray-200 hover:bg-gray-300"
            >
              Cancel
            </button>

            <button
              type="submit"
              disabled={isSubmitting}
              className="px-4 py-2 rounded-lg bg-orange-500 text-white hover:bg-orange-600 disabled:opacity-50"
            >
              {isSubmitting ? 'Saving…' : 'Submit'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

