'use client';

import { useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { useAuth } from '@/app/api/login/context/AuthContext';
import { db } from '@/app/api/firebase/firebase';
import { doc, getDoc, setDoc, serverTimestamp } from 'firebase/firestore';

export default function useLogin() {
  const router = useRouter();
  const sp = useSearchParams();
  const next = sp.get('next') || '/store';

  const { login, signInWithGoogle } = useAuth();

  // form
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  // ui
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isEmailLoading, setIsEmailLoading] = useState(false);
  const [isGoogleLoading, setIsGoogleLoading] = useState(false);

  async function ensureUserDoc(user) {
    const ref = doc(db, 'users', user.uid);
    const snap = await getDoc(ref);

    if (!snap.exists()) {
      // default user; you can manually change to 'admin' in Firestore
      await setDoc(ref, {
        email: user.email || null,
        role: 'user',
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });
      return 'user';
    } else {
      const data = snap.data();
      await setDoc(
        ref,
        {
          email: user.email || null,
          updatedAt: serverTimestamp(),
        },
        { merge: true }
      );
      return data.role || 'user';
    }
  }

  function handlePostLogin(role, mode) {
    if (mode === 'admin') {
      if (role !== 'admin') {
        setError("This account doesn't have admin access.");
        return;
      }
      router.push('/admin/dashboard');
    } else {
      router.push(next);
    }
  }

  const onEmailSubmit = async ({ mode = 'user' } = {}) => {
    setError('');
    setIsEmailLoading(true);
    try {
      const cred = await login(email, password);
      const role = await ensureUserDoc(cred.user);
      handlePostLogin(role, mode);
    } catch (err) {
      console.error(err);
      setError(err?.message || 'Failed to log in');
    } finally {
      setIsEmailLoading(false);
    }
  };

  const onGoogleSignIn = async ({ mode = 'user' } = {}) => {
    setError('');
    setIsGoogleLoading(true);
    try {
      const cred = await signInWithGoogle();
      const role = await ensureUserDoc(cred.user);
      handlePostLogin(role, mode);
    } catch (err) {
      console.error(err);
      setError(err?.message || 'Google sign-in failed');
    } finally {
      setIsGoogleLoading(false);
    }
  };

  return {
    email,
    setEmail,
    password,
    setPassword,
    showPassword,
    setShowPassword,
    error,
    isEmailLoading,
    isGoogleLoading,
    onEmailSubmit,
    onGoogleSignIn,
  };
}

'use client';
import { useEffect, useRef, useState } from 'react';
import {
  collection,
  query,
  where,
  orderBy,
  limit,
  startAfter,
  getDocs,
} from 'firebase/firestore';
import { db } from '@/app/api/firebase/firebase';

export default function useProducts({
  pageSize = 10,
  search = '',
  category = 'all',
  stock = 'all',
  // optional key to force reloads from callers (e.g. after delete)
  reloadKey = 0,
}) {
  const [products, setProducts] = useState([]);
  const [lastDoc, setLastDoc] = useState(null);
  const [loading, setLoading] = useState(true);

  // for next/previous pagination
  const [page, setPage] = useState(1);
  const cursorsRef = useRef([]);

  //reset pagination whenever filters/search/pagesize change

  useEffect(() => {
    setPage(1);
    setLastDoc(null);
    cursorsRef.current = [];
  }, [category, stock, search, pageSize]);

  const buildBaseQuery = (startDoc = null) => {
    const col = collection(db, 'products');

    // normalize inputs
    const normCategory = (category ?? 'all').trim();
    const normStock = stock ?? 'all';

    // stock thresholds aligned with UI:
    // in-stock: > 10, low-stock: 1..10, out-of-stock: 0
    const hasStockRange = normStock === 'in-stock' || normStock === 'low-stock';

    // IMPORTANT: when using range filters, first orderBy must be on that field
    let q = hasStockRange
      ? query(col, orderBy('stock'), orderBy('name'), limit(pageSize))
      : query(col, orderBy('name'), limit(pageSize));

    // category equality filter
    if (normCategory !== 'all') {
      q = query(q, where('category', '==', normCategory));
    }

    // stock filters
    if (normStock === 'in-stock') {
      q = query(q, where('stock', '>', 10));
    } else if (normStock === 'low-stock') {
      q = query(q, where('stock', '>', 0), where('stock', '<=', 10));
    } else if (normStock === 'out-of-stock') {
      q = query(q, where('stock', '==', 0));
      // equality doesn’t require orderBy on same field; using orderBy('name') is fine
    }

    if (startDoc) q = query(q, startAfter(startDoc));
    return q;
  };

  const fetchPage = async (startDoc = null) => {
    setLoading(true);
    try {
      const q = buildBaseQuery(startDoc);
      const snap = await getDocs(q);
      let rows = snap.docs.map((d) => ({ id: d.id, ...d.data() }));

      // local search (simple contains) — note this searches within the fetched page
      const term = (search || '').toLowerCase().trim();
      if (term) {
        rows = rows.filter(
          (p) =>
            p.name?.toLowerCase().includes(term) ||
            p.sku?.toLowerCase().includes(term)
        );
      }

      setProducts(rows);
      setLastDoc(snap.docs[snap.docs.length - 1] || null);

      cursorsRef.current[page] = startDoc || null;
    } catch (err) {
      console.error('Error fetching products:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const startDoc = page === 1 ? null : cursorsRef.current[page];
    fetchPage(startDoc);
    // include reloadKey so callers can force a refetch (increment the key)
  }, [page, category, stock, search, pageSize, reloadKey]);

  const loadNextPage = async () => {
    if (!lastDoc) return;
    cursorsRef.current[page + 1] = lastDoc;
    setPage((p) => p + 1);
  };

  const loadPrevPage = async () => {
    if (page <= 1) return;
    setPage((p) => p - 1);
  };

  return { products, loading, page, loadNextPage, loadPrevPage };
}

