+'use client';
+
+import { useEffect, useState, useMemo } from 'react';
+import { useParams, useRouter } from 'next/navigation';
+import { db } from '@/app/api/firebase/firebase';
+import { doc, getDoc } from 'firebase/firestore';
+import {
+  ArrowLeft,
