            Check Your Email
          </h1>
          <p className="text-gray-600 mb-6">
            We&apos;ve sent a password reset link to{" "}
            <span className="font-semibold">{email}</span>
          </p>
          <p className="text-sm text-gray-500 mb-6">
            If you don&apos;t see the email, check your spam folder or try
            again.
          </p>
          <div className="space-y-3">
            <button
              onClick={() => setEmailSent(false)}
              className="flex justify-center w-full bg-sec hover:bg-[#13aa95] text-white font-semibold py-2 px-4 rounded-xl transition-colors cursor-pointer"
            >
              Send Another Email
            </button>
            <Link
              href="/sign-in"
              className="block w-full border border-slate-300 hover:bg-slate-100 text-gray-700 font-semibold py-2 px-4 rounded-xl transition-colors"
            >
              Back to Sign In
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#d8e9fe] to-[#62a4fa] flex items-center justify-center px-4">
      <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-8">
        <div className="mb-6">
          <Link
            href="/sign-in"
            className="inline-flex items-center gap-2 text-gray-600 hover:text-gray-800 transition-colors"
          >
            <FaArrowLeft className="w-4 h-4" />
            Back to Sign In
          </Link>
        </div>

        <div className="text-center mb-8">
          <h1 className="text-2xl font-semibold text-gray-800 mb-2">
            Forgot Password?
          </h1>
          <p className="text-gray-600">
