      >
        <input
          type="email"
          name="email"
          required
          placeholder="Email"
          className="border border-slate-300 rounded-xl px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-sec focus:border-transparent"
          disabled={loading}
          autoComplete="off"
