router.put('/updateuser', fetchuser, upload.single('attachedImage'), async (req, res) => {
  const userId = req.user.id;
  const { firstName, lastName, username, location, gender, bio } = req.body;

  // saved in temporary folder
  let idOfAvatar = null;
  if (req.file !== undefined) {
    try {
      const auth = new google.auth.GoogleAuth({
        keyFile: './routes/cqkey.json',
        scopes: ['https://www.googleapis.com/auth/drive']
      })

      const driveService = google.drive({
        version: 'v3',
        auth
      })

      const fileMetaData = {
        'name': req.file.filename,
        'parents': [GOOGLE_API_FOLDER_ID]
      }

      const media = {
        mimeType: 'image/jpg',
        body: fs.createReadStream(req.file.path)
      }

      const response = await driveService.files.create({
        resource: fileMetaData,
        media: media,
        field: 'id'
      })
      idOfAvatar = response.data.id;

      setTimeout(() => {
        fs.unlink(req.file.path, (err) => {
            if (err) {
                throw err;
            }
            console.log("Delete File successfully.");
        });
    }, 5000);

    } catch (err) {
      console.log('Upload file error in google drive', err)
    }
  }

  try {
    let user = await User.findById(userId);
