'use client';

import { useMemo, useState } from 'react';

export default function useCatalogFilters(allProducts) {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [priceRange, setPriceRange] = useState('all');
  const [stockFilter, setStockFilter] = useState('all');
  const slug = (s) => s.toLowerCase().replace(/\s+/g, '-');

  const filtered = useMemo(() => {
    return (allProducts || [])
      .filter((p) =>
        selectedCategory === 'all'
          ? true
          : slug(p.category) === selectedCategory
      )
      .filter((p) => {
        if (priceRange === 'all') return true;
        if (priceRange === 'under50') return p.price < 50;
        if (priceRange === '50to100') return p.price >= 50 && p.price <= 100;
        if (priceRange === 'over100') return p.price > 100;
        return true;
      })
      .filter((p) =>
        stockFilter === 'all'
          ? true
          : stockFilter === 'instock'
          ? p.inStock
          : !p.inStock
      )
      .filter((p) =>
        searchQuery.trim()
          ? p.name.toLowerCase().includes(searchQuery.toLowerCase())
          : true
      );
  }, [allProducts, selectedCategory, priceRange, stockFilter, searchQuery]);

  const clearFilters = () => {
    setSearchQuery('');
    setSelectedCategory('all');
    setPriceRange('all');
    setStockFilter('all');
  };

  return {
    // state
    searchQuery,
    selectedCategory,
    priceRange,
    stockFilter,
    // setters
    setSearchQuery,
    setSelectedCategory,
    setPriceRange,
    setStockFilter,
    // derived
    filtered,
    clearFilters,
  };
}

// app/hooks/useLogin.jsx
'use client';

import { useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { useAuth } from '@/app/api/login/context/AuthContext';
import { db } from '@/app/api/firebase/firebase';
import { doc, getDoc, setDoc, serverTimestamp } from 'firebase/firestore';

export default function useLogin() {
  const router = useRouter();
  const sp = useSearchParams();
  const next = sp.get('next') || '/store';

  const { login, signInWithGoogle } = useAuth();

  // form
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  // ui
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [isEmailLoading, setIsEmailLoading] = useState(false);
  const [isGoogleLoading, setIsGoogleLoading] = useState(false);

  async function ensureUserDoc(user) {
    const ref = doc(db, 'users', user.uid);
    const snap = await getDoc(ref);

    if (!snap.exists()) {
      // default user; you can manually change to 'admin' in Firestore
      await setDoc(ref, {
        email: user.email || null,
        role: 'user',
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });
      return 'user';
    } else {
      const data = snap.data();
      await setDoc(
        ref,
        {
          email: user.email || null,
          updatedAt: serverTimestamp(),
        },
        { merge: true }
      );
      return data.role || 'user';
    }
  }

  function handlePostLogin(role, mode) {
    if (mode === 'admin') {
      if (role !== 'admin') {
        setError("This account doesn't have admin access.");
        return;
      }
      router.push('/admin/dashboard');
    } else {
      router.push(next);
    }
  }

  const onEmailSubmit = async ({ mode = 'user' } = {}) => {
    setError('');
    setIsEmailLoading(true);
    try {
      const cred = await login(email, password);
      const role = await ensureUserDoc(cred.user);
      handlePostLogin(role, mode);
    } catch (err) {
      console.error(err);
      setError(err?.message || 'Failed to log in');
    } finally {
      setIsEmailLoading(false);
    }
  };

  const onGoogleSignIn = async ({ mode = 'user' } = {}) => {
    setError('');
    setIsGoogleLoading(true);
    try {
      const cred = await signInWithGoogle();
      const role = await ensureUserDoc(cred.user);
      handlePostLogin(role, mode);
    } catch (err) {
      console.error(err);
      setError(err?.message || 'Google sign-in failed');
    } finally {
      setIsGoogleLoading(false);
    }
  };

  return {
    email,
    setEmail,
    password,
    setPassword,
    showPassword,
    setShowPassword,
    error,
    isEmailLoading,
    isGoogleLoading,
    onEmailSubmit,
    onGoogleSignIn,
  };
}

